_BONE_EXAM = re.compile(r"dxa|dexa|bone\s*dens|densitom|οστικ|οστεο|πυκνοτητ", re.I)
_OSTEOPENIA = re.compile(r"osteopen|οστεοπεν", re.I)
_OSTEOPOROSIS = re.compile(r"(?<!no\s)(?<!not\s)(?<!μη\s)(?<!χωρις\s)(osteopor|οστεοπορ)", re.I)
_SKIP_ROW = re.compile(r"ward|troch|inter", re.I)  # not diagnostic regions on the hip
_TCOL = re.compile(r"t[\s\-–]*score", re.I)


def enabled() -> bool:
    return os.environ.get("LIFESTYLE_INFO", "off").strip().lower() in ("on", "1", "true", "yes")


def _num(s: str):
    s = (s or "").replace("−", "-").replace("–", "-").replace(",", ".").strip()
    m = re.fullmatch(r"-?\d+(?:\.\d+)?", s)
    return float(s) if m else None


def bone_level(exam: dict):
    """'osteoporosis' | 'low' | None for one cleaned exam dict (see dossier._clean_exam)."""
    title = f"{exam.get('exam_title') or ''} {exam.get('exam_type') or ''}"
    concl = " ".join(f"{c.get('item', '')} {c.get('detail', '')}" for c in exam.get("conclusion") or [])
    if not (_BONE_EXAM.search(title) or _BONE_EXAM.search(concl)):
        return None
    tmin = None
    for sec in exam.get("sections") or []:
        cols = sec.get("columns") or []
        idx = next((i for i, c in enumerate(cols) if _TCOL.search(str(c))), None)
        if idx is None:
            continue
        for r in sec.get("rows") or []:
            if not r or _SKIP_ROW.search(str(r[0])):
                continue
            v = _num(r[idx]) if idx < len(r) else None
            if v is not None and (tmin is None or v < tmin):
                tmin = v
    if (tmin is not None and tmin <= -2.5) or _OSTEOPOROSIS.search(concl):
        return "osteoporosis"
    if (tmin is not None and tmin <= -1.0) or _OSTEOPENIA.search(concl):
        return "low"
    return None


def topics_for_exams(exams: list) -> dict:
    """{'bone': 'low'|'osteoporosis'} for the topics the exams trigger (worst level wins)."""
    out = {}
    for e in exams or []:
        lv = bone_level(e)
        if lv and (out.get("bone") != "osteoporosis"):
            out["bone"] = lv
    return out


def build(exams: list, lang: str = "el"):
    """Returns None or {'heading','note','blocks':[{'title','lines':[str],'sources':[...]}],'review','scope'}.
    Only items with at least one verified source are emitted."""
    lg = "el" if lang == "el" else "en"
    lb = LABELS[lg]
    blocks = []
    for topic, level in topics_for_exams(exams).items():
        lines, used = [], []
        if level == "osteoporosis":
            lines.append(EXTRA_OSTEOPOROSIS[lg])
        for it in ITEMS[topic]:
            srcs = [s for s in it["sources"] if s in SOURCES]
            if not srcs or not it[lg]:
                continue
            lines.append(it[lg])
            used += [s for s in srcs if s not in used]
        if lines:
            blocks.append({"title": lb["title"], "lines": lines,
                           "sources": [dict(SOURCES[s], key=s) for s in used]})
    if not blocks:
        return None
    return {"heading": lb["h"], "note": lb["note"], "scope": SCOPE_NOTE[lg], "blocks": blocks,
            "review": (f"{lb['rev']} {REVIEWED_BY}" if REVIEWED_BY else lb["unrev"]),
            "src_label": lb["src"]}


def render_html(sec: dict, num: int) -> str:
    e = _html.escape
    parts = [f'<section class="exam lifestyle"><h2><span class="num">{num:02d}</span>{e(sec["heading"])}</h2>',
             f'<p class="note">{e(sec["note"])}</p><p class="note">{e(sec["scope"])}</p>',
             f'<p class="note"><b>{e(sec["review"])}</b></p>']
    for b in sec["blocks"]:
        parts.append(f"<h3>{e(b['title'])}</h3><ul>" + "".join(f"<li>{e(x)}</li>" for x in b["lines"]) + "</ul>")
        parts.append(f'<p class="note">{e(sec["src_label"])}: ' + "; ".join(
            f'<a href="https://doi.org/{e(s["doi"])}">{e(s["doi"])}</a> (PMID {e(s["pmid"])})' for s in b["sources"]) + "</p>")
    parts.append("</section>")
    return "".join(parts)
